__NUXT_JSONP__("/it/how-to-apply/visa_overseas", (function(a){return {data:[{details:{slug:"it",pageTitle:"Applying for Long-term Study Abroad | Mentor Language Institute",pageDescription:a,title:"Applying for Long-term Study Abroad",image:"\u002Fimages\u002Fvisa-overseas\u002Fvisa.jpg",category:[{title:a,list_content:["A person living outside the United States","A person planning to stay in America for over 90 days","A person attending a language school(Educational institution) in the U.S."]},{title:"Application Steps",image:"\u002Fimages\u002Fvisa-overseas\u002Fsteps-en.jpg",ordered_content:["Apply to MLI","Submit The Documents","Receive your I-20","Visa application \u002F Interview","Receive your Visa","Leave for the U.S."],content:["It usually takes about \u003Cspan class='ymarker'\u003E3 months\u003C\u002Fspan\u003Ein order to obtain a student visa and study abroad. It is reommended to leave as much time as possible to complete the application process. Please apply \u003Cspan class='hutoaka'\u003Eat least three months in advance.\u003C\u002Fspan\u003EIf applying less than 3 months prior to departure, please inform our staff."]},{title:"About the steps after application",image:"\u002Fimages\u002Fvisa-overseas\u002Fmli-short-en.jpg",content:["After students have applied, the iMLI system processes the application. \u003Cbr \u002F\u003EStudents can follow the process which is listed on the iMLI."]},{title:"Apply Online",content:["Fill out the information about your visa status\u003Cbr \u002F\u003EContact us via iMLI for all inquiries","Apply from below."]}],btn_label:"Online Application Form",admission:{link:"\u002Fit\u002Fadmission",content:["*Please have your credit card in hand."]},dir:"\u002Fvisa-overseas",path:"\u002Fvisa-overseas\u002Fit",extension:".json",createdAt:"2026-10-22T16:31:31.335Z",updatedAt:"2025-05-26T12:06:28.030Z"}}],fetch:{},mutations:void 0}}("Who is elgible to apply for a student visa?")));